// Compact laundry fill/run cycle controller.
// Level probe on A0 (10 mV/cm), fill valve on D9, drum motor on D10.
// Reset button on D4 (pull-up) returns to IDLE.

const int LEVEL_PIN = A0;
const int VALVE_PIN = 9;
const int MOTOR_PIN = 10;
const int RESET_PIN = 4;
const float EMPTY_CM = 10.0f;
const float FULL_CM = 25.0f;
const float RUN_MIN_CM = 20.0f;
const float MV_PER_CM = 10.0f;
const unsigned long TICK_MS = 40;
const unsigned long STATUS_MS = 1000;

enum CycleState
{
    ST_IDLE = 0,
    ST_FILL = 1,
    ST_RUN = 2
};

CycleState state = ST_IDLE;
unsigned long lastTick = 0;
unsigned long lastStatus = 0;
float levelCm = 0.0f;

float readLevelCm()
{
    int raw = analogRead(LEVEL_PIN);
    float mv = raw * (5000.0f / 1023.0f);
    return mv / MV_PER_CM;
}

void driveOutputs()
{
    digitalWrite(VALVE_PIN, state == ST_FILL ? HIGH : LOW);
    digitalWrite(MOTOR_PIN, state == ST_RUN ? HIGH : LOW);
}

void printStatus()
{
    Serial.print("laundry st=");
    Serial.print((int)state);
    Serial.print(" cm=");
    Serial.println(levelCm, 1);
}

void setup()
{
    pinMode(VALVE_PIN, OUTPUT);
    pinMode(MOTOR_PIN, OUTPUT);
    pinMode(RESET_PIN, INPUT_PULLUP);
    driveOutputs();
    Serial.begin(9600);
    lastTick = millis();
    lastStatus = millis();
}

void loop()
{
    unsigned long now = millis();

    if (now - lastTick >= TICK_MS)
    {
        lastTick = now;
        levelCm = readLevelCm();

        if (digitalRead(RESET_PIN) == LOW)
        {
            state = ST_IDLE;
        }
        else if (state == ST_IDLE && levelCm >= RUN_MIN_CM)
        {
            state = ST_RUN;
        }
        else if (state == ST_IDLE && levelCm < EMPTY_CM)
        {
            state = ST_FILL;
        }
        else if (state == ST_FILL && levelCm >= FULL_CM)
        {
            state = ST_RUN;
        }
        else if (state == ST_RUN && levelCm < RUN_MIN_CM)
        {
            state = ST_IDLE;
        }

        driveOutputs();
    }

    if (now - lastStatus >= STATUS_MS)
    {
        lastStatus = now;
        printStatus();
    }
}

// Loft cooling fan with hysteresis and a boost button.
// TMP-style linear probe on A3 (10 mV/°C), fan on D5, boost on D4.

const int TEMP_PIN = A3;
const int FAN_PIN = 5;
const int BOOST_PIN = 4;

const float ON_C = 36.0f;
const float OFF_C = 32.0f;
const float MV_PER_C = 10.0f;
const unsigned long SAMPLE_MS = 50;
const unsigned long LOG_MS = 1000;
const unsigned long CONFIRM_MS = 100;

bool fanOn = false;
unsigned long onSince = 0;
unsigned long offSince = 0;
bool onTiming = false;
bool offTiming = false;
unsigned long boostSince = 0;
bool boostTiming = false;
unsigned long lastSample = 0;
unsigned long lastLog = 0;
float tempC = 0.0f;

float sampleTempC()
{
    int raw = analogRead(TEMP_PIN);
    float mv = raw * (5000.0f / 1023.0f);
    return mv / MV_PER_C;
}

void driveFan(bool on)
{
    fanOn = on;
    digitalWrite(FAN_PIN, on ? HIGH : LOW);
}

void logLine()
{
    Serial.print("loft: ");
    Serial.print(tempC, 1);
    Serial.print(" C fan=");
    Serial.println(fanOn ? "ON" : "OFF");
}

void setup()
{
    pinMode(FAN_PIN, OUTPUT);
    pinMode(BOOST_PIN, INPUT_PULLUP);
    digitalWrite(FAN_PIN, LOW);
    Serial.begin(9600);
    lastSample = millis();
    lastLog = millis();
}

void loop()
{
    unsigned long now = millis();

    if (now - lastSample >= SAMPLE_MS)
    {
        lastSample = now;
        tempC = sampleTempC();

        bool boostLow = (digitalRead(BOOST_PIN) == LOW);
        if (boostLow)
        {
            if (!boostTiming)
            {
                boostTiming = true;
                boostSince = now;
            }
        }
        else
        {
            boostTiming = false;
        }

        if (boostTiming && (now - boostSince >= CONFIRM_MS))
        {
            onTiming = false;
            offTiming = false;
            driveFan(true);
        }
        else
        {
            if (tempC >= ON_C)
            {
                if (!onTiming)
                {
                    onTiming = true;
                    onSince = now;
                }
            }
            else
            {
                onTiming = false;
            }
            if (tempC <= OFF_C)
            {
                if (!offTiming)
                {
                    offTiming = true;
                    offSince = now;
                }
            }
            else
            {
                offTiming = false;
            }

            if (onTiming && (now - onSince >= CONFIRM_MS))
            {
                driveFan(true);
            }
            else if (offTiming && (now - offSince >= CONFIRM_MS))
            {
                driveFan(false);
            }
        }
    }

    if (now - lastLog >= LOG_MS)
    {
        lastLog = now;
        logLine();
    }
}

