// Compressed-air manifold pressure logger for the workshop.
// Transducer on A2: 10 mV/kPa with 500 mV zero offset. Gauge lamp on D12.

const int PRESSURE_PIN = A2;
const int GAUGE_PIN = 12;
const float WARN_KPA = 90.0f;
const float MV_PER_KPA = 10.0f;
const float ZERO_MV = 500.0f;
const unsigned long SAMPLE_MS = 1000;
const unsigned long GAUGE_CONFIRM_MS = 400;

unsigned long lastSample = 0;
unsigned long readingCount = 0;
float lastKpa = 0.0f;
float minKpa = 9999.0f;
float maxKpa = 0.0f;
bool gaugeLit = false;
bool pendingLit = false;
unsigned long pendingSince = 0;

float readMillivolts()
{
    int raw = analogRead(PRESSURE_PIN);
    return raw * (5000.0f / 1023.0f);
}

float millivoltsToKpa(float mv)
{
    return (mv - ZERO_MV) / MV_PER_KPA;
}

void trackExtremes(float kpa)
{
    if (kpa < minKpa)
    {
        minKpa = kpa;
    }
    if (kpa > maxKpa)
    {
        maxKpa = kpa;
    }
}

void updateGauge(float kpa)
{
    bool wantLit = (kpa >= WARN_KPA);
    unsigned long now = millis();

    if (wantLit == gaugeLit)
    {
        pendingLit = gaugeLit;
        pendingSince = now;
        return;
    }

    if (wantLit != pendingLit)
    {
        pendingLit = wantLit;
        pendingSince = now;
        return;
    }

    if (now - pendingSince >= GAUGE_CONFIRM_MS)
    {
        gaugeLit = wantLit;
        digitalWrite(GAUGE_PIN, gaugeLit ? HIGH : LOW);
    }
}

void printReading()
{
    Serial.print("kPa: ");
    Serial.println(lastKpa, 1);
}

void setup()
{
    pinMode(GAUGE_PIN, OUTPUT);
    digitalWrite(GAUGE_PIN, LOW);
    Serial.begin(9600);
    lastSample = millis();
    pendingSince = lastSample;
}

void loop()
{
    float kpa = millivoltsToKpa(readMillivolts());
    updateGauge(kpa);

    unsigned long now = millis();
    if (now - lastSample < SAMPLE_MS)
    {
        return;
    }
    lastSample = now;

    lastKpa = kpa;
    readingCount++;
    trackExtremes(lastKpa);
    printReading();
}

// Yard path lamp dusk relay.
// Light sensor on A0 (mV as lux-ish units), relay on D8, manual on D3.

const int LIGHT_PIN = A0;
const int RELAY_PIN = 8;
const int MANUAL_PIN = 3;
const float ON_UNITS = 400.0f;
const float OFF_UNITS = 600.0f;
const unsigned long SAMPLE_MS = 40;
const unsigned long STATUS_MS = 1000;
const unsigned long CONFIRM_MS = 300;

bool relayOn = false;
unsigned long lastSample = 0;
unsigned long lastStatus = 0;
float lightU = 0.0f;
bool pendingOn = false;
bool havePending = false;
unsigned long pendingSince = 0;

float readLightUnits()
{
    int raw = analogRead(LIGHT_PIN);
    return raw * (5000.0f / 1023.0f);
}

void setRelay(bool on)
{
    relayOn = on;
    digitalWrite(RELAY_PIN, on ? HIGH : LOW);
}

void printStatus()
{
    Serial.print("yard u=");
    Serial.print(lightU, 0);
    Serial.print(" relay=");
    Serial.println(relayOn ? "ON" : "OFF");
}

void setup()
{
    pinMode(RELAY_PIN, OUTPUT);
    pinMode(MANUAL_PIN, INPUT_PULLUP);
    setRelay(false);
    Serial.begin(9600);
    lastSample = millis();
    lastStatus = millis();
}

void loop()
{
    unsigned long now = millis();

    if (now - lastSample >= SAMPLE_MS)
    {
        lastSample = now;
        lightU = readLightUnits();
        bool manual = (digitalRead(MANUAL_PIN) == LOW);

        if (manual)
        {
            havePending = false;
            setRelay(true);
        }
        else
        {
            bool wantOn = relayOn;
            bool candidate = false;

            if (lightU < ON_UNITS)
            {
                candidate = true;
                wantOn = true;
            }
            else if (lightU > OFF_UNITS)
            {
                candidate = true;
                wantOn = false;
            }

            if (!candidate || wantOn == relayOn)
            {
                havePending = false;
            }
            else
            {
                if (!havePending || pendingOn != wantOn)
                {
                    havePending = true;
                    pendingOn = wantOn;
                    pendingSince = now;
                }
                else if (now - pendingSince >= CONFIRM_MS)
                {
                    havePending = false;
                    setRelay(wantOn);
                }
            }
        }
    }

    if (now - lastStatus >= STATUS_MS)
    {
        lastStatus = now;
        printStatus();
    }
}
